function updateSoftKillDoctrine(dt){
    if(!softKillAutoDoctrine){
      softKillDoctrineState.eaAssignments=[];softKillDoctrineState.activeEaKey=null;softKillDoctrineState.schedulerAgeS=0;
      softKillDoctrineState.lastStep=simStepCounter;return softKillDoctrineState;
    }
    rebuildSoftKillEaAssignments();
    softKillDoctrineState.schedulerAgeS+=Math.max(0,Number(dt)||0);
    const frame=Math.max(SIM_FIXED_DT,SOFT_KILL_DOCTRINE.eaSchedulerFrameS);
    while(softKillDoctrineState.schedulerAgeS+1e-12>=frame){
      softKillDoctrineState.schedulerAgeS-=frame;advanceSoftKillEaSchedule();
    }
    if(!softKillDoctrineState.activeEaKey && softKillDoctrineState.eaAssignments.length) advanceSoftKillEaSchedule();
    softKillDoctrineCleanupResponses();
    const cand=softKillDoctrineChaffCandidate();
    if(cand){
      const fired=deployOwnChaffForThreat(cand.th,{automatic:true,responseId:cand.rid});
      if(fired>0){
        cand.rec.salvos=(cand.rec.salvos??0)+1;cand.rec.lastFiredStep=simStepCounter;cand.rec.lastRangeKm=cand.th.rangeKm??null;cand.rec.lastTtcS=cand.th.ttcS??null;
        softKillDoctrineState.lastAutoChaffStep=simStepCounter;
        softKillDoctrineState.lastAutoChaff={step:simStepCounter,key:cand.th.key,responseId:cand.rid,rangeKm:cand.th.rangeKm??null,ttcS:cand.th.ttcS??null,fired};
      }
    }
    nulkaAuto15B();
    softKillDoctrineState.lastStep=simStepCounter;softKillDoctrineState.revision++;
    return softKillDoctrineState;
  }

